const response = await fetch("http://localhost:8000/reverse", {
  method: "POST",
  headers: { "Content-Type": "application/json" },
  body: JSON.stringify({"text": "Hello, Mintlify!"}),
});
console.log(await response.json());

package main

import (
	"fmt"
	"io"
	"net/http"
	"strings"
)

func main() {
	body := strings.NewReader(`{"text": "Hello, Mintlify!"}`)
	resp, err := http.Post("http://localhost:8000/reverse", "application/json", body)
	if err != nil {
		panic(err)
	}
	defer resp.Body.Close()
	out, _ := io.ReadAll(resp.Body)
	fmt.Println(string(out))
}

